cat > "C:/Users/VM Oct26/AppData/Local/Temp/claude/C--Users-User1-Desktop-dark-raiders/8a09e991-b4f4-4b23-b10f-ded92e837fc3/scratchpad/mk-cw-shadowstore.ps1" <<'EOF'
$g=[IO.File]::ReadAllText($(if($env:MK_SRC){$env:MK_SRC}else{'C:\claudecode\dark raiders\dark_raiders.html'}))
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L "(?m)^    if\(SHADSPR\.ss!==ss\)\{ SHADSPR\.m=\{\}; SHADSPR\.n=0; SHADSPR\.ss=ss; \}\r?\n    R=\[Math\.round\(rx\),Math\.round\(ry\),Math\.round\(a\*100\)\]; k=R\.join\(','\);\r?\n"
$r1=@'
    // v28.xx (cw-shadowstore): the store used to empty whenever the sprite scale changed, and the world (ss 1) and the bigger figures (ss 2)
    // changed it twice a frame, so every shadow painted a new canvas every frame. ss is part of the key now; the 300 cap stays.
    R=[Math.round(rx),Math.round(ry),Math.round(a*100)]; k=ss+':'+R.join(',');

'@.Replace("`r",'')
$chk=@'
  {v:'VER',what:'the shadow store keeps its sprites when the sprite scale changes between world and figures, so frames paint no new shadow canvases',
   run:function(){
     if(typeof shadowE!=='function'||typeof SHADSPR==='undefined') return 'no shadow store';
     var rc=document.createElement, rd=wc.drawImage, made=0, dr=[], ow, i, n1, n3;
     try{
       __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       if(!__state()||!__state().player) return 'SKIP: no raid';
       document.createElement=function(t){ if(String(t).toLowerCase()==='canvas') made++; return rc.apply(document,arguments); };
       wc.drawImage=function(im,x,y,w,h){ if(im&&im.width&&arguments.length===5) dr.push(w); return rd.apply(wc,arguments); };
       SHADSPR.m={}; SHADSPR.n=0; SHADSPR.ss=0;
       for(i=0;i<3;i++){
         wc.save(); wc.setTransform(1,0,0,1,0,0); shadowE(100,100,37,19,0.41); wc.restore();
         wc.save(); wc.setTransform(2,0,0,2,0,0); shadowE(100,100,37,19,0.41); wc.restore();
         if(i===0){ n1=made; }
       }
       n3=made;
       if(n3!==n1) return 'frames 2 and 3 made '+(n3-n1)+' new shadow canvases (the store emptied on every scale change)';
       if(Object.keys(SHADSPR.m).length<2) return 'the store holds '+Object.keys(SHADSPR.m).length+' entries, not one per scale';
       if(dr.length<6||Math.abs(dr[0]-dr[1])>1) return 'a shadow at scale 1 and 2 differs in size: '+dr[0]+' vs '+dr[1];
       return null;
     } finally {
       document.createElement=rc; wc.drawImage=rd;
       try{ __endRaid('abandon'); }catch(_e){}
       __topClear();
     } }},
'@.Replace("`r",'')
$d=[ordered]@{
  title='GROUND SHADOWS KEEP THEIR SPRITES ACROSS SCALES'
  why='The ground shadow store emptied itself whenever the sprite scale changed. The world and the bigger figures use different scales, so it emptied twice a frame and every shadow painted a new canvas every frame: slow frames, garbage collection and memory growth that crawled the full test run. The scale is now part of the key.'
  now='Ground shadows no longer repaint their sprites every frame; raids with many bodies and boxes run smoother.'
  edits=@( [ordered]@{ anchor=$a1; replacement=$r1 } )
  check=$chk
}
[IO.File]::WriteAllText('C:\claudecode\dark raiders\tools\handoff\drafts\draft-cw-shadowstore.json',($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
'written'
EOF
